// ============================================
// Configuratie — pas deze waarden aan!
// ============================================
const ODOO_URL = 'https://jouw-odoo-url.com';
const ODOO_DB = 'jouw-database';
const ODOO_USER = 'admin';
const ODOO_PASSWORD = 'jouw-api-key';

const input = $input.first().json;

return [{
  json: {
    config: { url: ODOO_URL, db: ODOO_DB, user: ODOO_USER, password: ODOO_PASSWORD },
    input: input,
    rpc: {
      jsonrpc: '2.0',
      id: 1,
      method: 'call',
      params: {
        service: 'common',
        method: 'authenticate',
        args: [ODOO_DB, ODOO_USER, ODOO_PASSWORD, {}]
      }
    }
  }
}];

// Route op basis van action: 'save' of 'delete'
const authResponse = $input.first().json;
const uid = authResponse.result;
if (!uid) throw new Error('Odoo authenticatie mislukt!');

const setup = $('Setup').first().json;
const config = setup.config;
const webhookData = setup.input.body || setup.input;
const action = webhookData.action || 'save';

return [{
  json: { config, uid, action, webhookData }
}];

// Bouw het unlink (delete) request voor Odoo
const item = $input.first().json;
const { config, uid, webhookData } = item;
const odooIds = webhookData.odoo_ids || [];

if (odooIds.length === 0) {
  throw new Error('Geen odoo_ids opgegeven om te verwijderen.');
}

// Odoo unlink verwijdert meerdere records in één keer
return [{
  json: {
    config,
    uid,
    odooIds,
    rpc: {
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          config.db, uid, config.password,
          'project.task', 'unlink',
          [odooIds]
        ]
      }
    }
  }
}];

// Verwerk delete response
const response = $input.first().json;
const prepDelete = $('Prep Delete').first().json;

if (response.error) {
  throw new Error(
    'Odoo fout bij verwijderen: ' +
    (response.error.data?.message || response.error.message || JSON.stringify(response.error))
  );
}

return [{
  json: {
    success: true,
    action: 'delete',
    deleted_ids: prepDelete.odooIds
  }
}];

// Save pad: bouw stage lookup request
const item = $input.first().json;
const { config, uid } = item;

return [{
  json: {
    config,
    uid,
    rpc: {
      jsonrpc: '2.0',
      id: 2,
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          config.db, uid, config.password,
          'project.task.type', 'search_read',
          [[['name', 'in', ['Blokken', 'Verdiepen', 'Collectoren', 'Kringen']]]],
          { fields: ['name'] }
        ]
      }
    }
  }
}];

// Verwerk stage lookup resultaten en flatten alle taken
const stageResponse = $input.first().json;
const stageRecords = stageResponse.result || [];

// Bouw stageMap: { 'Blokken': 5, 'Verdiepen': 6, ... }
const stageMap = {};
for (const rec of stageRecords) {
  stageMap[rec.name] = rec.id;
}

// Haal config + uid op
const prepNode = $('Prep Stage Lookup').first().json;
const config = prepNode.config;
const uid = prepNode.uid;

// Haal originele webhook data op
const setup = $('Setup').first().json;
const webhookData = setup.input.body || setup.input;
const projectId = webhookData.project_id;
const gebouwen = webhookData.gebouwen || [];

// Sla stageMap op in static data voor gebruik in de loop
const staticData = $getWorkflowStaticData('global');
staticData.stageMap = stageMap;
staticData.idMap = {};
staticData.results = [];

// Flatten alle taken in volgorde: gebouwen → verdiepen → collectoren → kringen
const tasks = [];

for (let gi = 0; gi < gebouwen.length; gi++) {
  const g = gebouwen[gi];
  tasks.push({
    ref: `g_${gi}`,
    parentRef: null,
    level: 'gebouw',
    odooId: g.odoo_id ? parseInt(g.odoo_id) : null,
    values: {
      name: g.naam,
      project_id: projectId,
      stage_id: stageMap['Blokken'] || false,
      parent_id: false
    },
    meta: { gi, naam: g.naam }
  });

  for (let vi = 0; vi < (g.verdiepen || []).length; vi++) {
    const v = g.verdiepen[vi];
    tasks.push({
      ref: `v_${gi}_${vi}`,
      parentRef: `g_${gi}`,
      level: 'verdiep',
      odooId: v.odoo_id ? parseInt(v.odoo_id) : null,
      values: {
        name: `Verdieping ${v.nummer}`,
        project_id: projectId,
        stage_id: stageMap['Verdiepen'] || false
      },
      meta: { gi, vi, nummer: v.nummer }
    });

    for (let ci = 0; ci < (v.collectoren || []).length; ci++) {
      const c = v.collectoren[ci];
      tasks.push({
        ref: `c_${gi}_${vi}_${ci}`,
        parentRef: `v_${gi}_${vi}`,
        level: 'collector',
        odooId: c.odoo_id ? parseInt(c.odoo_id) : null,
        values: {
          name: c.naam || `Collector ${c.nummer}`,
          project_id: projectId,
          stage_id: stageMap['Collectoren'] || false
        },
        meta: { gi, vi, ci, nummer: c.nummer }
      });

      for (let ki = 0; ki < (c.kringen || []).length; ki++) {
        const k = c.kringen[ki];
        tasks.push({
          ref: `k_${gi}_${vi}_${ci}_${ki}`,
          parentRef: `c_${gi}_${vi}_${ci}`,
          level: 'kring',
          odooId: k.odoo_id ? parseInt(k.odoo_id) : null,
          values: {
            name: `Kring ${k.nummer}`,
            project_id: projectId,
            stage_id: stageMap['Kringen'] || false
          },
          meta: { gi, vi, ci, ki, nummer: k.nummer }
        });
      }
    }
  }
}

return tasks.map(task => ({
  json: { config, uid, task }
}));

// Bouw het JSON-RPC create/write request
const item = $input.first().json;
const { config, uid, task } = item;

// Haal parent_id op uit static data (eerder aangemaakte records)
const staticData = $getWorkflowStaticData('global');
const idMap = staticData.idMap || {};

const values = { ...task.values };

// Voeg parent_id toe als er een parent is
if (task.parentRef && idMap[task.parentRef]) {
  values.parent_id = idMap[task.parentRef];
}

let rpc;
if (task.odooId) {
  // Update bestaand record
  rpc = {
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [config.db, uid, config.password, 'project.task', 'write', [[task.odooId], values]]
    }
  };
} else {
  // Nieuw record aanmaken
  rpc = {
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [config.db, uid, config.password, 'project.task', 'create', [values]]
    }
  };
}

return [{
  json: { config, uid, task, rpc }
}];

// Verwerk Odoo response, sla ID op voor kinderen
const response = $input.first().json;
const buildReq = $('Build Request').first().json;
const { task } = buildReq;

if (response.error) {
  throw new Error(
    `Odoo fout bij ${task.ref}: ` +
    (response.error.data?.message || response.error.message || JSON.stringify(response.error))
  );
}

const staticData = $getWorkflowStaticData('global');

// Bepaal het odoo_id (bij create is het result het nieuwe ID, bij write is het true)
const odooId = task.odooId || response.result;

// Sla ID op zodat kinderen het als parent_id kunnen gebruiken
staticData.idMap[task.ref] = odooId;

// Sla resultaat op voor de eindresponse
staticData.results.push({
  ref: task.ref,
  parentRef: task.parentRef,
  level: task.level,
  odooId: odooId,
  meta: task.meta
});

return [{ json: { done: true, ref: task.ref, odooId } }];

// Bouw het geneste resultaat op
const staticData = $getWorkflowStaticData('global');
const results = staticData.results || [];

const setup = $('Setup').first().json;
const webhookData = setup.input.body || setup.input;
const projectId = webhookData.project_id;

const gebouwen = results.filter(r => r.level === 'gebouw');
const verdiepen = results.filter(r => r.level === 'verdiep');
const collectoren = results.filter(r => r.level === 'collector');
const kringen = results.filter(r => r.level === 'kring');

const output = gebouwen.map(g => ({
  odoo_id: g.odooId,
  naam: g.meta.naam,
  verdiepen: verdiepen
    .filter(v => v.meta.gi === g.meta.gi)
    .map(v => ({
      odoo_id: v.odooId,
      nummer: v.meta.nummer,
      collectoren: collectoren
        .filter(c => c.meta.gi === g.meta.gi && c.meta.vi === v.meta.vi)
        .map(c => ({
          odoo_id: c.odooId,
          nummer: c.meta.nummer,
          kringen: kringen
            .filter(k => k.meta.gi === g.meta.gi && k.meta.vi === v.meta.vi && k.meta.ci === c.meta.ci)
            .map(k => ({
              odoo_id: k.odooId,
              nummer: k.meta.nummer
            }))
        }))
    }))
}));

// Ruim static data op
delete staticData.idMap;
delete staticData.stageMap;
delete staticData.results;

return [{
  json: {
    success: true,
    project_id: projectId,
    gebouwen: output
  }
}];
